row_rules.PR_INCOME_LOT:
if app_rules_pr.bypass = 0 then  -- rows written by the APP_ACT_PR buttons: legacy values kept
if inserting then
  -- PR_INCOME_LOT PRE-INSERT / WHEN-CREATE-RECORD / TRNS_TYPE_CODE and SUPPLIER_CODE WVI
  :new.st_srv_asst_flag := nvl(:new.st_srv_asst_flag, 1);
  :new.post_flag := nvl(:new.post_flag, 0);
  :new.lot_serial := nvl(:new.lot_serial, app_rules_pr.next_lot_serial(:new.trns_type_code, :new.trns_serial));
  :new.doc_no := nvl(:new.doc_no, app_rules_pr.next_lot_doc_no);
  :new.store_code := nvl(:new.store_code, app_rules_pr.type_store(:new.trns_type_code));
  if :new.supplier_code is not null and nvl(:new.currency_code, 1) = 1 and app_rules_pr.supplier_currency(:new.supplier_code) <> 1 then
    :new.currency_code := app_rules_pr.supplier_currency(:new.supplier_code);
    :new.currency_rate := app_rules_pr.currency_rate(:new.currency_code, :new.arrival_date);
  end if;
  :new.currency_code := nvl(:new.currency_code, 1);
  :new.currency_rate := nvl(:new.currency_rate, 1);
end if;
end if;

row_rules.PR_INCOME_LOT_DET:
if app_rules_pr.bypass = 0 then  -- rows written by the APP_ACT_PR buttons: legacy values kept
-- PR_INCOME_LOT_DET PRE-INSERT / PRE-UPDATE / WHEN-CREATE-RECORD
app_rules_pr.lot_line_guard(:new.trns_type_code, :new.trns_serial);
if :new.item_code is not null then
  :new.group_code := nvl(:new.group_code, app_rules_pr.item_group(:new.item_code));
  :new.unit_code := nvl(:new.unit_code, app_rules_pr.basic_unit(:new.group_code, :new.item_code));
end if;
if inserting then
  :new.order_trns_type_code_det := nvl(:new.order_trns_type_code_det, app_rules_pr.lot_value(:new.trns_type_code, :new.trns_serial, 'ORDER_TYPE'));
  :new.order_trns_serial_det := nvl(:new.order_trns_serial_det, app_rules_pr.lot_value(:new.trns_type_code, :new.trns_serial, 'ORDER_SERIAL'));
  if app_rules_pr.lot_value(:new.trns_type_code, :new.trns_serial, 'ORDER_TYPE') is not null
     and (app_rules_pr.chg(:new.order_trns_type_code_det, app_rules_pr.lot_value(:new.trns_type_code, :new.trns_serial, 'ORDER_TYPE')) = 1
          or app_rules_pr.chg(:new.order_trns_serial_det, app_rules_pr.lot_value(:new.trns_type_code, :new.trns_serial, 'ORDER_SERIAL')) = 1) then
    raise_application_error(-20139, 'رقم أمر الشراء في السطر يختلف عن أمر الشراء في رأس الرسالة');
  end if;
  if :new.order_trns_type_code_det is not null and app_rules_pr.order_date(:new.order_trns_type_code_det, :new.order_trns_serial_det) is null then
    raise_application_error(-20139, 'رقم أمر الشراء غير موجود');
  end if;
  if :new.production_date is null or :new.sales_price is null or :new.sales_disc_ratio is null or :new.lot_number is null
     or :new.expire_date is null or :new.unit_code is null then
    raise_application_error(-20121, 'يجب إدخال محددات الشحنات: رقم التشغيلة وتاريخ الصلاحية وتاريخ الانتاج وسعر البيع ونسبة خصم البيع - الصنف ' || :new.item_code);
  end if;
  :new.arrival_date := nvl(:new.arrival_date, app_rules_pr.lot_arrival(:new.trns_type_code, :new.trns_serial));
  :new.store_code := nvl(:new.store_code, app_rules_pr.lot_value(:new.trns_type_code, :new.trns_serial, 'STORE'));
end if;
if nvl(:new.income_bonus, 0) < 0 then
  raise_application_error(-20139, 'الكمية المجانية لا بد أن يكون أكبر او يساوى الصفر');
end if;
if (inserting or app_rules_pr.chg(:new.income_quantity, :old.income_quantity) + app_rules_pr.chg(:new.income_bonus, :old.income_bonus) > 0)
   and nvl(:new.income_quantity, 0) + nvl(:new.income_bonus, 0) <= 0 then
  raise_application_error(-20139, 'يجب إدخال الكمية المستلمة - الصنف ' || :new.item_code);
end if;
app_rules_pr.disc_chain(inserting, :new.vn_price, :old.vn_price,
                        :new.disc1_ratio, :old.disc1_ratio, :new.disc1_value, :old.disc1_value,
                        :new.disc2_ratio, :old.disc2_ratio, :new.disc2_value, :old.disc2_value,
                        :new.disc3_ratio, :old.disc3_ratio, :new.disc3_value, :old.disc3_value);
:new.income_basic_qty := (nvl(:new.income_quantity, 0) + nvl(:new.income_bonus, 0))
                         * app_rules_pr.unit_factor(:new.group_code, :new.item_code, :new.unit_code);
end if;

